"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "react-resizable-panels";
export const resizableVariants = cva(
  "v-resizable [height:var(--h,240px)] [background:var(--card)] [border-radius:22px] [overflow:hidden] [box-shadow:inset_0_0_0_1px_var(--v-border)] [isolation:isolate] flex",
  {
    variants: { variant: { default: "", v: "-v" } },
    defaultVariants: { variant: "default" },
  },
);
export type ResizablePanelGroupProps = React.ComponentProps<
  typeof Primitive.Group
> &
  VariantProps<typeof resizableVariants> & {
    direction?: "horizontal" | "vertical";
  };
export function ResizablePanelGroup({
  className,
  variant,
  direction,
  orientation,
  elementRef,
  style,
  ...props
}: ResizablePanelGroupProps) {
  const morphRef = useMorph<HTMLDivElement>("cards", elementRef);
  const resolved =
    orientation ?? direction ?? (variant === "v" ? "vertical" : "horizontal");
  return (
    <Primitive.Group
      elementRef={morphRef}
      data-slot="resizable"
      data-part="root"
      data-resizable=""
      orientation={resolved}
      style={{ height: "var(--h,240px)", ...style }}
      className={cn(
        resizableVariants({ variant: resolved === "vertical" ? "v" : "default" }),
        className,
      )}
      {...props}
    />
  );
}
export type ResizablePanelProps = React.ComponentProps<typeof Primitive.Panel>;
export function ResizablePanel({
  className,
  minSize = "15%",
  maxSize = "85%",
  ...props
}: ResizablePanelProps) {
  return (
    <Primitive.Panel
      data-slot="resizable-panel"
      data-part="content"
      minSize={minSize}
      maxSize={maxSize}
      className={cn(
        "v-resizable__pane min-w-0 overflow-auto",
        className,
      )}
      {...props}
    />
  );
}
export type ResizableHandleProps = React.ComponentProps<
  typeof Primitive.Separator
> & { withHandle?: boolean };
export function ResizableHandle({
  className,
  withHandle = true,
  children,
  ...props
}: ResizableHandleProps) {
  return (
    <Primitive.Separator
      data-slot="resizable-handle"
      data-part="thumb"
      data-with-handle={withHandle || undefined}
      className={cn(
        "v-resizable__handle grid place-items-center touch-none shrink-0 basis-2",
        className,
      )}
      {...props}
    >
      {children}
    </Primitive.Separator>
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-resizable__pane:where([data-slot="resizable-panel"] > *) {
  padding: var(--s-4);
  overflow: auto;
  min-width: 0;
}
.v-resizable__handle:where([data-slot="resizable"], [data-slot^="resizable-"]) {
  background: transparent;
  cursor: col-resize;
  place-items: center;
  touch-action: none;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle {
  cursor: row-resize;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  )::before {
  content: "";
  width: 2px;
  height: 28px;
  border-radius: 1px;
  background: var(--v-border);
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle::before {
  width: 28px;
  height: 2px;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):hover::before,
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible::before {
  background: var(--v-pink);
}
.v-resizable__pane:where([data-slot="resizable-panel"] > *) {
  padding: 18px 20px;
  gap: 6px;
  align-content: start;
  background: var(--v-canvas);
}
:where([data-slot="resizable-panel"]:last-child) > .v-resizable__pane {
  background: var(--surface-work);
}
.v-resizable__pane:where([data-slot="resizable-panel"] > *)
  > b {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.v-resizable__pane:where([data-slot="resizable-panel"] > *)
  .v-caps {
  margin-bottom: 4px;
}
.v-resizable__handle:where([data-slot="resizable"], [data-slot^="resizable-"]) {
  position: relative;
  background: var(--card);
  cursor: col-resize;
  place-items: center;
  touch-action: none;
  transition: background var(--t-micro);
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  )::before {
  content: "";
  width: 6px;
  height: 44px;
  border-radius: 999px;
  background: var(--v-edge);
  opacity: 0.6;
  transition: all var(--t-micro) var(--enter);
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  )::after {
  content: "";
  position: absolute;
  width: 2px;
  height: 14px;
  background: var(--v-canvas);
  border-radius: 1px;
  opacity: 0;
  transition: opacity var(--t-micro);
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):hover::before,
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible::before {
  background: var(--v-pink);
  opacity: 1;
  height: 56px;
  width: 8px;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):hover::after,
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible::after {
  opacity: 1;
  background: var(--ink-fixed);
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):active::before,
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-dragging
  .v-resizable__handle::before {
  background: var(--v-ink);
  opacity: 1;
  width: 8px;
  height: 64px;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):active::after,
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-dragging
  .v-resizable__handle::after {
  background: var(--v-canvas);
  opacity: 1;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible {
  outline: none;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible::before {
  box-shadow:
    0 0 0 2px var(--v-canvas),
    0 0 0 4px var(--ring);
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle {
  cursor: row-resize;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle::before {
  width: 44px;
  height: 6px;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle::after {
  width: 14px;
  height: 2px;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle:hover::before {
  width: 56px;
  height: 8px;
}
.v-resizable__handle:where([data-slot="resizable"], [data-slot^="resizable-"]) {
  position: relative;
  width: 14px;
  cursor: col-resize;
  background: transparent;
  place-items: center;
  flex: none;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  )::before {
  content: "";
  width: 4px;
  height: 36px;
  border-radius: 999px;
  background: var(--v-edge);
  transition:
    background var(--t-micro),
    height var(--t-element) var(--enter);
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):hover::before,
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible::before,
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):active::before,
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-dragging
  .v-resizable__handle::before {
  background: var(--v-pink-deep);
  height: 52px;
}
.v-resizable__handle:where(
    [data-slot="resizable"],
    [data-slot^="resizable-"]
  ):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
  border-radius: 8px;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle {
  width: auto;
  height: 14px;
  cursor: row-resize;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle::before {
  width: 36px;
  height: 4px;
}
.v-resizable:where([data-slot="resizable"], [data-slot^="resizable-"]).-v
  .v-resizable__handle:hover::before {
  width: 52px;
  height: 4px;
}
.v-resizable__pane:where([data-slot="resizable-panel"] > *) {
  border-radius: 16px;
}
:root[data-mode="dark"]
  .v-resizable__pane:where([data-slot="resizable-panel"] > *) {
  background: var(--v-beige);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="resizable"],
  [data-slot^="resizable-"],
  [data-slot="resizable"]::before,
  [data-slot="resizable"]::after,
  [data-slot^="resizable-"]::before,
  [data-slot^="resizable-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="resizable-panel"] > .v-resizable__pane {
  display: grid;
  /* The panel owns scrolling; its composed content owns spacing. */
  padding: 0;
}
[data-slot="resizable-handle"] {
  display: grid;
  flex-basis: 14px;
}
[data-slot="resizable-handle"]:not([data-with-handle])::before,
[data-slot="resizable-handle"]:not([data-with-handle])::after {
  display: none;
}

}
